cd /src/wasm3 && apply_patch <<'PATCH'
*** Begin Patch
*** Update File: source/m3_compile.h
@@
 extern const M3OpInfo c_operations [];
 extern const M3OpInfo c_operationsFC [];

-static inline
-const M3OpInfo* GetOpInfo(m3opcode_t opcode) {
-    switch (opcode >> 8) {
-    case 0x00: return &c_operations[opcode];
-    case 0xFC: return &c_operationsFC[opcode & 0xFF];
-    default:   return NULL;
-    }
-}
+// Lookup opcode metadata.
+//
+// SECURITY: This must return NULL for unknown/unsupported opcodes. In
+// particular, the 0xFC "extended" opcode space is sparsely populated and must
+// be bounds-checked to avoid out-of-bounds reads from the global opcode tables.
+const M3OpInfo* GetOpInfo (m3opcode_t opcode);
*** End Patch
PATCH

cd /src/wasm3 && python - <<'PY'
from pathlib import Path
path = Path('source/m3_compile.h')
text = path.read_text()
old = "static inline
const M3OpInfo* GetOpInfo(m3opcode_t opcode) {
    switch (opcode >> 8) {
    case 0x00: return &c_operations[opcode];
    case 0xFC: return &c_operationsFC[opcode & 0xFF];
    default:   return NULL;
    }
}
"
if old not in text:
    raise SystemExit('pattern not found in m3_compile.h')
new = "// Lookup opcode metadata.
//
// SECURITY: Must return NULL for unknown/unsupported opcodes. In particular,
// the 0xFC "extended" opcode space is sparsely populated and must be
// bounds-checked to avoid out-of-bounds reads from the global opcode tables.
const M3OpInfo* GetOpInfo (m3opcode_t opcode);
"
path.write_text(text.replace(old, new))
print('updated', path)
PY

cd /src/wasm3 && python - <<'PY'
from pathlib import Path
path = Path('source/m3_compile.c')
text = path.read_text()
insert_marker = "const M3OpInfo c_operationsFC [] =
{"
if insert_marker not in text:
    raise SystemExit('marker not found for c_operationsFC')
# Ensure we don't duplicate
if 'M3_COUNT_OF (c_operationsFC)' in text and 'GetOpInfo (m3opcode_t opcode)' in text:
    print('GetOpInfo already present')
    raise SystemExit(0)
# Find a good insertion point after c_operationsFC definition and before Compile_BlockStatements
# We'll append helper near the tables. Place after the c_operationsFC array closes '};'
idx = text.find('const M3OpInfo c_operationsFC')
end_idx = text.find('};', idx)
if end_idx == -1:
    raise SystemExit('end of c_operationsFC array not found')
end_idx = text.find('
', end_idx) + 1
helper = "
// Lookup opcode metadata. See declaration in m3_compile.h.
// Returns NULL for unknown/unsupported opcodes.
const M3OpInfo* GetOpInfo (m3opcode_t opcode)
{
    switch (opcode >> 8)
    {
        case 0x00:
            return & c_operations[opcode];

        case 0xFC: {
            const u32 sub = (u32) (opcode & 0xFF);
            if (LIKELY(sub < M3_COUNT_OF (c_operationsFC)))
                return & c_operationsFC[sub];
            return NULL;
        }

        default:
            return NULL;
    }
}
"
text2 = text[:end_idx] + helper + text[end_idx:]
path.write_text(text2)
print('inserted GetOpInfo into', path)
PY
